require 'includes/functions.php';if(!logged()){flash('Connectez-vous pour commander.','warning');go('login.php');}$cart=$_SESSION['cart']??[];if(!$cart)go('shop.php');$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,price,stock FROM products WHERE id IN ($marks) AND status='active'");$s->execute($ids);$products=$s->fetchAll();$total=0;foreach($products as $p){$q=(int)$cart[$p['id']];if($q>$p['stock']){flash('Stock insuffisant pour '.$p['name'],'warning');go('cart.php');}$total+=$q*$p['price'];}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');if(!$name||!$phone||!$address||!$city){flash('Remplissez tous les champs.','danger');}else{try{$pdo->beginTransaction();$ref='FZ'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare("INSERT INTO orders(user_id,order_number,status,subtotal,shipping_cost,total,customer_name,customer_phone,shipping_address) VALUES(?,?,'pending',?,0,?,?,?,?)");$s->execute([$_SESSION['user']['id'],$ref,$total,$total,$name,$phone,$address.', '.$city.', Tunisie']);$oid=$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity) VALUES(?,?,?,?,?)");$upd=$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?");foreach($products as $p){$q=(int)$cart[$p['id']];$upd->execute([$q,$p['id'],$q]);if(!$upd->rowCount())throw new Exception('Stock insuffisant');$ins->execute([$oid,$p['id'],$p['name'],$p['price'],$q]);}$pay=$pdo->prepare("INSERT INTO payments(order_id,method,status,amount) VALUES(?,'cash_on_delivery','pending',?)");$pay->execute([$oid,$total]);$pdo->commit();unset($_SESSION['cart']);flash('Commande '.$ref.' confirmée.');go('account.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Erreur lors de la commande. Réessayez.','danger');}}}
$title='Commande';$base='';require 'includes/header.php';?><section class="banner"><div class="container"><h1>FINALISER LA COMMANDE</h1></div></section><section class="container section cartlayout"><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><h2>Livraison</h2><label>Nom complet<input required name="name" value="<?=e($_SESSION['user']['full_name'])?>"></label><label>Téléphone<input required name="phone"></label><label>Adresse<input required name="address"></label><label>Ville<input required name="city"></label><button class="btn full">CONFIRMER · PAIEMENT À LA LIVRAISON</button></form><aside class="summary"><h2>Résumé</h2><?php foreach($products as $p):?><p><?=e($p['name'])?> × <?=(int)$cart[$p['id']]?> <b><?=money($p['price']*$cart[$p['id']])?></b></p><?php endforeach?><hr><h3>Total : <?=money($total)?></h3></aside></section><?php require 'includes/footer.php';?>
